public static class BuildDeformableMud
{
 const string Folder="Assets/Game/Generated/DeformableMud";
 struct V {public Vector3 p,n;public Vector2 uv;public V Lerp(V b,float t)=>new V{p=Vector3.Lerp(p,b.p,t),n=Vector3.Lerp(n,b.n,t),uv=Vector2.Lerp(uv,b.uv,t)};}
 sealed class Builder {
  public List<Vector3> p=new List<Vector3>(),n=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int>[] triangles;
  Dictionary<(Vector3Int,Vector3Int,Vector2Int),int> ids=new Dictionary<(Vector3Int,Vector3Int,Vector2Int),int>();
  public Builder(int count){triangles=Enumerable.Range(0,count).Select(_=>new List<int>()).ToArray();}
  int Add(V v){var key=(Vector3Int.RoundToInt(v.p*100000),Vector3Int.RoundToInt(v.n*10000),Vector2Int.RoundToInt(v.uv*100000));if(ids.TryGetValue(key,out int i))return i;i=p.Count;ids[key]=i;p.Add(v.p);n.Add(v.n.normalized);uv.Add(v.uv);return i;}
  public void Tri(V a,V b,V c,int sub){if(Vector3.Cross(b.p-a.p,c.p-a.p).sqrMagnitude<1e-14f)return;triangles[sub].Add(Add(a));triangles[sub].Add(Add(b));triangles[sub].Add(Add(c));}
  public void Poly(List<V> poly,int sub){for(int i=1;i<poly.Count-1;i++)Tri(poly[0],poly[i],poly[i+1],sub);}
  public Mesh Mesh(string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(p);m.SetNormals(n);m.SetUVs(0,uv);m.subMeshCount=triangles.Length;for(int s=0;s<triangles.Length;s++)m.SetTriangles(triangles[s],s);m.RecalculateBounds();m.RecalculateTangents();return m;}
 }
 static List<V> Clip(List<V> poly,Func<V,float> distance,bool inside){var result=new List<V>();if(poly.Count==0)return result;V previous=poly[poly.Count-1];float pd=distance(previous)*(inside?1:-1);foreach(var v in poly){float d=distance(v)*(inside?1:-1);if((d>=0)!=(pd>=0)){float t=pd/(pd-d);result.Add(previous.Lerp(v,t));}if(d>=0)result.Add(v);previous=v;pd=d;}return result;}
 static void Dense(Builder b,V a,V c,V d,int sub,int depth=0){float ac=(a.p-c.p).sqrMagnitude,cd=(c.p-d.p).sqrMagnitude,da=(d.p-a.p).sqrMagnitude;if(Mathf.Max(ac,cd,da)<=.22f*.22f||depth>16){b.Tri(a,c,d,sub);return;}if(ac>=cd&&ac>=da){var m=a.Lerp(c,.5f);Dense(b,a,m,d,sub,depth+1);Dense(b,m,c,d,sub,depth+1);}else if(cd>=da){var m=c.Lerp(d,.5f);Dense(b,a,c,m,sub,depth+1);Dense(b,a,m,d,sub,depth+1);}else{var m=d.Lerp(a,.5f);Dense(b,a,c,m,sub,depth+1);Dense(b,m,c,d,sub,depth+1);}}
 static Mesh Save(Mesh mesh,string path){var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(old);return old;}
 static Mesh Collision(Mesh source,string path,Vector3 extrusion=default){var m=UnityEngine.Object.Instantiate(source);m.name=source.name+" collision";int[] t=source.triangles;var both=new List<int>(t);for(int i=0;i<t.Length;i+=3)both.AddRange(new[]{t[i],t[i+2],t[i+1]});if(extrusion.sqrMagnitude>0){var vertices=source.vertices.ToList();var weld=new Dictionary<Vector3Int,int>();var ids=new int[vertices.Count];for(int i=0;i<vertices.Count;i++){var key=Vector3Int.RoundToInt(vertices[i]*1000);if(!weld.TryGetValue(key,out int id)){id=weld.Count;weld[key]=id;}ids[i]=id;}var edges=new Dictionary<(int,int),(int,int,int)>();for(int i=0;i<t.Length;i+=3)for(int j=0;j<3;j++){int a=t[i+j],b=t[i+(j+1)%3];var key=ids[a]<ids[b]?(ids[a],ids[b]):(ids[b],ids[a]);if(edges.TryGetValue(key,out var edge))edges[key]=(edge.Item1,edge.Item2,edge.Item3+1);else edges[key]=(a,b,1);}foreach(var edge in edges.Values){if(edge.Item3!=1)continue;int n=vertices.Count;var a=vertices[edge.Item1];var b=vertices[edge.Item2];vertices.AddRange(new[]{a,b,a+extrusion,b+extrusion});both.AddRange(new[]{n,n+1,n+2,n+1,n+3,n+2,n+2,n+1,n,n+2,n+3,n+1});}m.Clear();m.indexFormat=IndexFormat.UInt32;m.SetVertices(vertices);}m.subMeshCount=1;m.SetTriangles(both,0);m.RecalculateBounds();return Save(m,path);}
 static Material Wet(Material source){string path=Folder+"/Wet "+source.name.Replace('/','_')+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m!=null)return m;m=new Material(source){name="Wet "+source.name};if(m.HasProperty("_BaseColor")){var color=m.GetColor("_BaseColor");m.SetColor("_BaseColor",new Color(color.r*.62f,color.g*.57f,color.b*.48f,color.a));}if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",.42f);if(m.HasProperty("_SnowAmount"))m.SetFloat("_SnowAmount",0);if(m.HasProperty("_UseRoughness"))m.SetFloat("_UseRoughness",0);if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",new Color(.55f,.43f,.30f,1));AssetDatabase.CreateAsset(m,path);return m;}
 static int Patch(GameObject sceneRoot,Vector3 centre,Vector3 forward,string id,SoftGroundProfile soilProfile,float halfLength=5,float halfWidth=2.6f)
 {
  forward.y=0;var rotation=Quaternion.LookRotation(forward.normalized);Matrix4x4 frame=Matrix4x4.TRS(centre,rotation,Vector3.one),inverse=frame.inverse;
  var filters=sceneRoot.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.gameObject.activeInHierarchy&&f.sharedMesh!=null&&f.GetComponent<MeshCollider>()!=null&&f.GetComponent<MeshCollider>().enabled&&f.GetComponent<MeshRenderer>()!=null&&f.GetComponent<MeshRenderer>().enabled&&(f.GetComponent<ForestGroundPatch>()!=null||f.GetComponent<SoftGroundRuts>()!=null||f.GetComponent<ForestDrivingSurface>()!=null)).ToArray();
  var patchRoot=new GameObject("Deformable mud "+id);patchRoot.transform.SetParent(sceneRoot.transform,true);patchRoot.transform.SetPositionAndRotation(centre,rotation);int parts=0;
  foreach(var f in filters){var renderer=f.GetComponent<MeshRenderer>();var bounds=renderer.bounds;if(centre.y<bounds.min.y-2||centre.y>bounds.max.y+2)continue;var mesh=f.sharedMesh;var positions=mesh.vertices;var normals=mesh.normals;var uv=mesh.uv;var outside=new Builder(mesh.subMeshCount);var inside=new Builder(mesh.subMeshCount);var world=f.transform.localToWorldMatrix;var normalMatrix=world.inverse.transpose;
   Func<V,float>[] planes={v=>inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(v.p)).x+halfWidth,v=>halfWidth-inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(v.p)).x,v=>inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(v.p)).z+halfLength,v=>halfLength-inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(v.p)).z};
   Func<int,V> vertex=i=>new V{p=positions[i],n=normals.Length==positions.Length?normals[i]:Vector3.up,uv=uv.Length==positions.Length?uv[i]:Vector2.zero};
   for(int sub=0;sub<mesh.subMeshCount;sub++){var tris=mesh.GetTriangles(sub);for(int t=0;t<tris.Length;t+=3){var a=vertex(tris[t]);var b=vertex(tris[t+1]);var c=vertex(tris[t+2]);var localA=inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(a.p));var localB=inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(b.p));var localC=inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(c.p));if(Mathf.Max(localA.x,localB.x,localC.x)<-halfWidth||Mathf.Min(localA.x,localB.x,localC.x)>halfWidth||Mathf.Max(localA.z,localB.z,localC.z)<-halfLength||Mathf.Min(localA.z,localB.z,localC.z)>halfLength){outside.Tri(a,b,c,sub);continue;}
    var poly=new List<V>{a,b,c};foreach(var plane in planes){outside.Poly(Clip(poly,plane,false),sub);poly=Clip(poly,plane,true);if(poly.Count==0)break;}
    for(int j=0;j<poly.Count;j++){var v=poly[j];v.p=inverse.MultiplyPoint3x4(world.MultiplyPoint3x4(v.p));v.n=inverse.MultiplyVector(normalMatrix.MultiplyVector(v.n)).normalized;
     // A shallow local bowl holds water; the imported FBX is never edited.
     float bowl=(v.p.x+.55f)*(v.p.x+.55f)/1.3f+(v.p.z+.7f)*(v.p.z+.7f)/2.2f;v.p.y-=.065f*Mathf.Max(0,1-bowl);poly[j]=v;}
    for(int j=1;j<poly.Count-1;j++)Dense(inside,poly[0],poly[j],poly[j+1],sub);
   }}
   if(inside.p.Count==0)continue;string token=id+" "+parts+" "+f.name;var outsideMesh=Save(outside.Mesh("Outside local mud "+token),Folder+"/Outside "+token+".asset");f.sharedMesh=outsideMesh;f.GetComponent<MeshCollider>().sharedMesh=Collision(outsideMesh,Folder+"/Outside collision "+token+".asset",f.transform.InverseTransformVector(Vector3.down*100));if(outside.p.Count==0){renderer.enabled=false;f.GetComponent<MeshCollider>().enabled=false;}var oldRuts=f.GetComponent<SoftGroundRuts>();if(oldRuts!=null)oldRuts.enabled=false;EditorUtility.SetDirty(f);EditorUtility.SetDirty(f.GetComponent<MeshCollider>());PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<MeshCollider>());
   var go=new GameObject("Soft soil "+parts+" "+f.name);go.transform.SetParent(patchRoot.transform,false);var dense=Save(inside.Mesh("Dense local mud "+token),Folder+"/Mud "+token+".asset");go.AddComponent<MeshFilter>().sharedMesh=dense;go.AddComponent<MeshRenderer>().sharedMaterials=renderer.sharedMaterials.Select(Wet).ToArray();go.AddComponent<MeshCollider>().sharedMesh=Collision(dense,Folder+"/Mud collision "+token+".asset");var surface=go.AddComponent<ForestDrivingSurface>();surface.cover=ForestDrivingSurface.Cover.Mud;surface.forwardGrip=.40f;surface.lateralGrip=.40f;surface.rollingResistance=.045f;surface.chainsImproveGrip=true;surface.chainedForwardGrip=.65f;surface.chainedLateralGrip=.65f;var ruts=go.AddComponent<SoftGroundRuts>();ruts.profile=soilProfile;ruts.fieldHalfSize=new Vector2(halfWidth,halfLength);ruts.maximumDepth=soilProfile.maximumDepthMetres;ruts.persistentId=id.StartsWith("main")?id+"/"+parts:"";parts++;
  }
  if(parts==0){UnityEngine.Object.DestroyImmediate(patchRoot);return 0;}
  Water(patchRoot,halfWidth,halfLength,id);return parts;
 }
 static void Water(GameObject root,float halfWidth,float halfLength,string id)
 {
  Physics.SyncTransforms();var colliders=root.GetComponentsInChildren<MeshCollider>();float min=float.MaxValue;var samples=new Dictionary<Vector2Int,Vector3>();const float spacing=.15f;
  for(int z=-8;z<=8;z++)for(int x=-6;x<=6;x++){float px=x*spacing-.55f,pz=z*spacing-.7f;if(x*x/36f+z*z/64f>1)continue;var start=root.transform.TransformPoint(new Vector3(px,3,pz));float best=float.MinValue;foreach(var collider in colliders)if(collider.Raycast(new Ray(start,Vector3.down),out var h,7))best=Mathf.Max(best,h.point.y);if(best==float.MinValue)continue;samples[new Vector2Int(x,z)]=new Vector3(start.x,best,start.z);min=Mathf.Min(min,best);}
  if(min==float.MaxValue)return;float level=min+.035f;var builder=new Builder(1);
  foreach(var pair in samples){var key=pair.Key;foreach(var tri in new[]{new[]{key,key+Vector2Int.up,key+Vector2Int.right},new[]{key+Vector2Int.right,key+Vector2Int.up,key+Vector2Int.one}}){if(!tri.All(k=>samples.ContainsKey(k)&&samples[k].y<level-.002f))continue;var v=tri.Select(k=>{var p=samples[k];p.y=level;return new V{p=root.transform.InverseTransformPoint(p),n=root.transform.InverseTransformDirection(Vector3.up),uv=new Vector2(k.x,k.y)*.12f};}).ToArray();builder.Tri(v[0],v[1],v[2],0);}}
  if(builder.p.Count==0)return;var go=new GameObject("Shallow puddle water");go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=Save(builder.Mesh("Puddle "+id),Folder+"/Puddle "+id+".asset");var renderer=go.AddComponent<MeshRenderer>();string path=Folder+"/Muddy water.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name="Muddy water";m.SetColor("_BaseColor",new Color(.10f,.075f,.035f,.72f));m.SetFloat("_Smoothness",.94f);m.SetFloat("_Surface",1);m.SetFloat("_SrcBlend",5);m.SetFloat("_DstBlend",10);m.SetFloat("_ZWrite",0);m.SetFloat("_Cull",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;AssetDatabase.CreateAsset(m,path);}renderer.sharedMaterial=m;renderer.shadowCastingMode=ShadowCastingMode.Off;
 }
 public static string Main()
 {
  if(Application.isPlaying)throw new Exception("Stop Play first");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets/Game/Generated","DeformableMud");if(GameObject.Find("Deformable mud main0")!=null)throw new Exception("Mud already configured");string path=Folder+"/Forest soft soil.asset";var profile=AssetDatabase.LoadAssetAtPath<SoftGroundProfile>(path);if(profile==null){profile=ScriptableObject.CreateInstance<SoftGroundProfile>();AssetDatabase.CreateAsset(profile,path);}var scene=EditorSceneManager.GetActiveScene();var sceneRoot=new GameObject("Local deformable road surfaces");int parts=0;
  // Process existing scene roots as one group, without moving the original forest transforms.
  foreach(var specification in new[]{(new Vector3(-40.62f,43.15f,44.16f),"main0"),(new Vector3(-72.29f,40.28f,41.5f),"main1")}){var allRoots=scene.GetRootGameObjects().Where(r=>r!=sceneRoot).ToArray();var temporary=new GameObject("TEMP clip group");var parents=allRoots.Select(r=>r.transform.parent).ToArray();foreach(var root in allRoots)root.transform.SetParent(temporary.transform,true);try{parts+=Patch(temporary,specification.Item1,Vector3.left,specification.Item2,profile);}finally{foreach(var root in allRoots)root.transform.SetParent(null,true);foreach(var t in temporary.GetComponentsInChildren<Transform>(true).Where(t=>t.parent==temporary.transform).ToArray())t.SetParent(sceneRoot.transform,true);UnityEngine.Object.DestroyImmediate(temporary);}}
  var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();foreach(var prefab in route.arms.SelectMany(a=>a.modules).Distinct()){string prefabPath=AssetDatabase.GetAssetPath(prefab);var contents=PrefabUtility.LoadPrefabContents(prefabPath);try{var block=contents.GetComponent<AuthoredForestBlock>();float d=Mathf.Min(18,block.length*.4f);var centre=contents.transform.TransformPoint(block.Point(d));var forward=contents.transform.TransformVector(block.Point(d+2)-block.Point(d));parts+=Patch(contents,centre,forward,"module "+prefab.name,profile,4,2.3f);PrefabUtility.SaveAsPrefabAsset(contents,prefabPath);}finally{PrefabUtility.UnloadPrefabContents(contents);}}
  var car=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();if(car.GetComponent<VehicleTyrePressure>()==null)car.gameObject.AddComponent<VehicleTyrePressure>();EditorUtility.SetDirty(profile);EditorUtility.SetDirty(car.profile.equipment);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");return "Saved local dense mud layers="+parts+"; original FBX preserved; visible/collision corridor cut together; pressure component added.";
 }
